<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 30px;
    background: #d9dade;
    display: flex;
    justify-content: center;
    font-family: "Songti SC","STSong","SimSun",serif;
  }
  .card {
    position: relative;
    width: 620px;
    background: #f5f1e6;
    background-image:
      linear-gradient(#eae5d6 1px, transparent 1px),
      linear-gradient(90deg, #eae5d6 1px, transparent 1px);
    background-size: 24px 24px;
    border: 2px dashed #b9b4a4;
    border-radius: 4px;
    padding: 26px 32px 40px 32px;
    color: #3a352c;
  }
  .header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
  }
  .header-left {
    display: flex;
    align-items: flex-start;
    gap: 14px;
  }
  .icon-circle {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 30%, #9aa3ad, #5c6570 70%);
    flex-shrink: 0;
    margin-top: 2px;
  }
  .num-kw {
    display: flex;
    flex-direction: column;
  }
  .page-num {
    font-size: 26px;
    font-weight: 600;
    color: #333;
    line-height: 1;
  }
  .keywords {
    margin-top: 26px;
    font-size: 12px;
    color: #6b665a;
    display: flex;
    align-items: center;
    gap: 6px;
  }
  .dots span {
    display: inline-block;
    width: 8px;
    height: 8px;
    border: 1px solid #a9a397;
    border-radius: 50%;
    margin-left: 4px;
  }
  .header-right {
    border-left: 1px solid #cfcabb;
    padding-left: 18px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-width: 150px;
    margin-top: 4px;
  }
  .field {
    display: flex;
    align-items: baseline;
    gap: 6px;
    font-size: 12px;
    color: #6b665a;
  }
  .field .line {
    flex: 1;
    border-bottom: 1px solid #cfcabb;
    height: 10px;
  }
  .divider {
    border: none;
    border-top: 1px solid #cfcabb;
    margin: 16px 0 20px 0;
  }
  .title {
    font-size: 19px;
    font-weight: 700;
    color: #2b2b2b;
    margin: 0 0 22px 0;
    letter-spacing: 1px;
  }
  .content {
    position: relative;
    display: flex;
    gap: 14px;
    align-items: flex-start;
  }
  .main-text {
    flex: 0 0 62%;
    font-size: 15px;
    line-height: 2.15;
    text-align: justify;
    color: #2f2b23;
  }
  .main-text p {
    margin: 0;
    text-indent: 2em;
  }
  mark {
    background: #f4c98a;
    background: linear-gradient(180deg, transparent 55%, #f6c98a 55%);
    padding: 0 1px;
  }
  .annotations {
    flex: 1;
    display: flex;
    flex-direction: column;
    font-size: 12.5px;
    color: #c0392b;
    line-height: 1.6;
  }
  .note {
    position: relative;
    padding-left: 6px;
  }
  .note::before {
    content: "";
    position: absolute;
    left: -14px;
    top: 6px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #c0392b;
  }
  .note1 { margin-top: 60px; }
  .note2 { margin-top: 175px; }
  .note3 { margin-top: 105px; }
  svg.lines {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
  }
</style>
</head>
