          <span class="dots"><span></span><span></span><span></span><span></span></span>
        </div>
      </div>
    </div>
    <div class="header-right">
      <div class="field"><span>Date:</span><div class="line"></div></div>
      <div class="field"><span>From:</span><div class="line"></div></div>
      <div class="field"><span>Time:</span><div class="line"></div></div>
    </div>
